{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-5gG0pI/src/policies.js","content":"/**
 * A token bucket policy. Each key gets an independent bucket that starts
 * full and refills by `refill` tokens per `per` ticks, tracked as an exact
 * fraction (numerator over the fixed denominator `per`) so partial periods
 * never lose precision.
 */
export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capacityNumerator = capacity * per
    this.states = new Map()
  }

  #stateFor(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { numerator: this.capacityNumerator, lastTick: tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key, tick)
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      const grown = state.numerator + this.refill * elapsed
      state.numerator = grown < this.capacityNumerator ? grown : this.capacityNumerator
      state.lastTick = tick
    }
  }

  allows(key) {
    return this.states.get(key).numerator >= this.per
  }

  record(key) {
    this.states.get(key).numerator -= this.per
  }
}

/**
 * A sliding window policy. Each key remembers the ticks of the requests it
 * recorded, and advancing forgets everything at or before `tick - span`.
 */
export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #stateFor(key) {
    let state = this.states.get(key)
    if (!state) {
      state = []
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const queue = this.#stateFor(key)
    const threshold = tick - this.span
    let dropped = 0
    while (dropped < queue.length && queue[dropped] <= threshold) dropped++
    if (dropped > 0) queue.splice(0, dropped)
  }

  allows(key) {
    return BigInt(this.states.get(key).length) < this.limit
  }

  record(key, tick) {
    this.states.get(key).push(tick)
  }
}
"}

