{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-5gG0pI/src/engine.js","content":"import { LineError } from './errors.js'
import { checkIdentifier, parseField } from './fields.js'
import { SlidingWindow, TokenBucket } from './policies.js'

/**
 * Parses a limiter file and replays its events, returning one result per
 * event in log order. Each result is `{ tick, key, allow, deniedBy }`,
 * where `deniedBy` is the name of the first policy on the route that
 * refused, or `null` when the event was allowed.
 *
 * Throws a {@link LineError} at the first invalid line.
 */
export function simulate(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const results = []
  let seenEvent = false
  let previousTick = null

  for (let index = 0; index < lines.length; index++) {
    const lineNumber = index + 1
    const raw = lines[index].trim()
    if (raw === '' || raw.startsWith('#')) continue

    const tokens = raw.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket') {
      requireNoEventYet(lineNumber, seenEvent)
      if (tokens.length !== 5) throw new LineError(lineNumber, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityRaw, refillRaw, perRaw] = tokens
      checkIdentifier(lineNumber, 'policy name', name)
      const capacity = parseField(lineNumber, 'capacity', 1, capacityRaw)
      const refill = parseField(lineNumber, 'refill', 0, refillRaw)
      const per = parseField(lineNumber, 'per', 1, perRaw)
      registerPolicy(lineNumber, policies, name, new TokenBucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      requireNoEventYet(lineNumber, seenEvent)
      if (tokens.length !== 4) throw new LineError(lineNumber, 'expected window <name> <limit> <span>')
      const [, name, limitRaw, spanRaw] = tokens
      checkIdentifier(lineNumber, 'policy name', name)
      const limit = parseField(lineNumber, 'limit', 0, limitRaw)
      const span = parseField(lineNumber, 'span', 1, spanRaw)
      registerPolicy(lineNumber, policies, name, new SlidingWindow(name, limit, span))
    } else if (directive === 'route') {
      requireNoEventYet(lineNumber, seenEvent)
      if (tokens.length < 3) throw new LineError(lineNumber, 'expected route <prefix> <policy>...')
      const [, prefix, ...policyNames] = tokens
      checkIdentifier(lineNumber, 'route prefix', prefix)
      const routePolicies = policyNames.map((name) => {
        const policy = policies.get(name)
        if (!policy) throw new LineError(lineNumber, `unknown policy ${name}`)
        return policy
      })
      if (routes.some((route) => route.prefix === prefix)) {
        throw new LineError(lineNumber, `prefix ${prefix} is routed twice`)
      }
      routes.push({ prefix, policies: routePolicies })
    } else if (directive === 'event') {
      if (tokens.length !== 3) throw new LineError(lineNumber, 'expected event <tick> <key>')
      const [, tickRaw, key] = tokens
      const tick = parseField(lineNumber, 'tick', 0, tickRaw)
      checkIdentifier(lineNumber, 'key', key)
      if (previousTick !== null && tick < previousTick) {
        throw new LineError(lineNumber, `tick ${tick} is before tick ${previousTick}`)
      }
      previousTick = tick
      seenEvent = true
      results.push(applyEvent(routes, tick, key))
    } else {
      throw new LineError(lineNumber, `unknown directive ${directive}`)
    }
  }

  return results
}

function requireNoEventYet(lineNumber, seenEvent) {
  if (seenEvent) throw new LineError(lineNumber, 'declarations must come before the first event')
}

function registerPolicy(lineNumber, policies, name, policy) {
  if (policies.has(name)) throw new LineError(lineNumber, `policy ${name} is declared twice`)
  policies.set(name, policy)
}

function routeFor(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (best === null || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

function applyEvent(routes, tick, key) {
  const route = routeFor(routes, key)
  if (!route) return { tick, key, allow: true, deniedBy: null }

  for (const policy of route.policies) policy.advance(key, tick)

  let deniedBy = null
  for (const policy of route.policies) {
    if (!policy.allows(key)) {
      deniedBy = policy.name
      break
    }
  }

  if (deniedBy === null) {
    for (const policy of route.policies) policy.record(key, tick)
    return { tick, key, allow: true, deniedBy: null }
  }
  return { tick, key, allow: false, deniedBy }
}
"}

